const PALNAME = { light: 'Light', dark: 'Dark' };
async function run(PAL, NAME) {
  await figma.loadAllPagesAsync();
  let page = figma.root.children.find(p => p.name === NAME);
  const nodes = {};
  if (page) {
    await figma.setCurrentPageAsync(page);
    for (const n of page.children) { const id = n.name.split(' · ')[0]; if (DATA.screens[id] && n.type === 'FRAME') nodes[id] = n; }
    for (const id in nodes) for (const c of [...nodes[id].children]) if (c.name.startsWith('Link → ')) c.remove();
    figma.notify('Found ' + Object.keys(nodes).length + ' screens, redoing the links…');
  } else {
    page = figma.createPage(); page.name = NAME; await figma.setCurrentPageAsync(page);
    await figma.loadFontAsync({ family: 'Inter', style: 'Bold' });
    let y = 0, done = 0, total = Object.keys(DATA.screens).length;
    for (const [gname, ids] of DATA.groups) {
      const label = figma.createText(); label.fontName = { family: 'Inter', style: 'Bold' }; label.fontSize = 64; label.characters = gname; label.x = 0; label.y = y; page.appendChild(label);
      y += 120; let x = 0, rowH = 0;
      for (const id of ids) {
        const sc = DATA.screens[id]; if (!sc) continue;
        const f = figma.createNodeFromSvg(sc.svg[PAL]); f.name = id + ' · ' + sc.name; f.x = x; f.y = y; f.clipsContent = true; page.appendChild(f);
        nodes[id] = f; x += f.width + 200; rowH = Math.max(rowH, f.height);
        if (++done % 10 === 0) figma.notify('Drawing screens: ' + done + ' of ' + total, { timeout: 1500 });
      }
      y += rowH + 300;
    }
  }
  let links = 0, failed = 0, firstErr = '';
  const ids = Object.keys(nodes);
  for (let i = 0; i < ids.length; i++) {
    const id = ids[i];
    for (const [x, yy, w, h, to, label] of DATA.screens[id].spots) {
      if (to === id || !nodes[to]) continue; // a link to the screen you are already on does nothing
      try {
        const r = figma.createRectangle(); r.name = 'Link → ' + to + ' · ' + label; nodes[id].appendChild(r);
        r.x = x; r.y = yy; r.resize(Math.max(w, 1), Math.max(h, 1)); r.fills = [];
        await r.setReactionsAsync([{ trigger: { type: 'ON_CLICK' }, actions: [{ type: 'NODE', destinationId: nodes[to].id, navigation: 'NAVIGATE', transition: null }] }]);
        links++;
      } catch (e) { failed++; if (!firstErr) firstErr = id + ' → ' + to + ': ' + e.message; }
    }
    if (i % 10 === 9) figma.notify('Wiring links: screen ' + (i + 1) + ' of ' + ids.length, { timeout: 1500 });
  }
  const starts = ['C05', 'C01', 'O05', 'N01', 'O01', 'V06', 'V01'].filter(i => nodes[i]);
  try { page.flowStartingPoints = starts.map(i => ({ nodeId: nodes[i].id, name: DATA.screens[i].name })); } catch (e) {}
  figma.viewport.scrollAndZoomIntoView(Object.values(nodes).slice(0, 6));
  return NAME + ': ' + ids.length + ' screens, ' + links + ' links' + (failed ? ', ' + failed + ' failed (first: ' + firstErr + ')' : '');
}
(async () => {
  const T = "Tezera Organiser"; const res = [];
  for (const p of DATA.pals) res.push(await run(p, DATA.pals.length > 1 ? T + ' · ' + PALNAME[p] : T));
  figma.closePlugin('Done. ' + res.join(' | ') + '. Press Present to click through.');
})().catch(e => figma.closePlugin('Import failed: ' + e.message));
